using System;using System.Drawing;using System.Windows.Forms;using System.Reflection;class SummaryTest{[STAThread]static void Main(){using(var f=new Atlas()){var flags=BindingFlags.Instance|BindingFlags.NonPublic;var t=typeof(Atlas);var m=(Chart)t.GetField("map",flags).GetValue(f);var r=(RichTextBox)t.GetField("summary",flags).GetValue(f);var data=new Inventory();var a=new Device("450E"){Linked=true};var b=new Device("Mini"){Linked=true};var c=new Device("localhost"){HostStatus="inaktiv"};data.Devices.AddRange(new[]{a,b,c});data.Links.Add(new Link(){A=a,B=b,Type="WLAN",Rx=25,Tx=null});data.Messages.Add("fritz.box · urn:dslforum-org:service:WLANConfiguration:1 · 403");m.SetData(data);t.GetMethod("UpdateSummary",flags).Invoke(f,new object[]{b});if(!r.Text.Contains("hier: unbekannt")||!r.Text.Contains("Gegenstelle: 25 dB")||r.Text.Contains("urn:")||!r.Text.Contains("Zugriff abgelehnt"))throw new Exception(r.Text);t.GetMethod("UpdateSummary",flags).Invoke(f,new object[]{c});if(!r.Text.Contains("inaktiv")||!r.Text.Contains("Keine aktive Verbindung"))throw new Exception(r.Text);m.Size=new Size(600,400);c.Pos=new PointF(300,300);using(var bmp=new Bitmap(600,400)){m.DrawToBitmap(bmp,m.ClientRectangle);bool ink=false;for(int x=250;x<350;x++)for(int y=322;y<340;y++)if(bmp.GetPixel(x,y).ToArgb()!=Color.White.ToArgb())ink=true;if(!ink)throw new Exception("Beschriftung fehlt");}Console.WriteLine("OK");}}}